import * as eFns from 'svelte/easing'
import * as tFns from 'svelte/transition'

export const TRANSITION_OPTS = {
  placement: 'top',
  transition: 'fade',
  easing: 'easeInOut',
  duration: 300,
  delay: 0,
  // css and tick not used for applyTransition (yet)
}

export const TRANSITION_OPT_KEYS = Object.keys(TRANSITION_OPTS)

const BUILT_IN_TRANSITIONS = [
  'fade',
  'blur',
  'fly',
  'slide',
  'scale',
  'draw',
  'crossfade',
]

export function applyTransition(node, params) {
  const opts = { ...TRANSITION_OPTS, ...params }
  const { easing, transition, ...rest } = opts

  const e = eFns[easing]

  if (BUILT_IN_TRANSITIONS.includes(transition)) {
    const t = tFns[transition]
    return t(node, {
      ...rest,
      easing: e,
      axis: getAxis(params.placement),
      ...getXY(params.placement),
    })
  }

  if (typeof transition === 'function') {
    return transition(node, {
      ...rest,
      easing: e,
    })
  }
}

// Used for slide transitions
function getAxis(placement) {
  if (placement === 'top' || placement === 'bottom') return 'y'
  if (placement === 'left' || placement === 'right') return 'x'
}

// Used for fly transitions
export function getXY(placement) {
  if (placement === 'top') return { x: 0, y: '-100%' }
  if (placement === 'bottom') return { x: 0, y: '100%' }
  if (placement === 'left') return { x: '-100%', y: 0 }
  if (placement === 'right') return { x: '100%', y: 0 }
}

// ========================================
// PUSH transition
// Made for drawer. Not used now.
// ========================================
export function push(node, params) {
  const { placement } = params
  const { width, height } = node.getBoundingClientRect()
  const canvasNode = document.querySelector('.Canvas')

  if (!width && !height) return

  return {
    ...params,
    tick(t, u) {
      const transformValues = getPushTransformValues({
        t,
        u,
        placement,
        width,
        height,
      })

      node.style.transform = transformValues.node
      canvasNode.style.transform = transformValues.canvas
    },
  }
}

export function getPushTransformValues({ t, u, placement, width, height }) {
  if (placement === 'right') {
    return {
      node: `translateX(${u * width}px)`,
      canvas: `translateX(${-1 * t * width}px)`,
    }
  }

  if (placement === 'left') {
    return {
      node: `translateX(${-1 * u * width}px)`,
      canvas: `translateX(${t * width}px)`,
    }
  }

  if (placement === 'top') {
    return {
      node: `translateY(${-1 * u * height}px)`,
      canvas: `translateY(${t * height}px)`,
    }
  }

  if (placement === 'bottom') {
    return {
      node: `translateY(${u * height}px)`,
      canvas: `translateY(${-1 * t * height}px)`,
    }
  }
}
